/* =========================================================
   🎭 文字图伪装魔法 (长按揭秘 + 自由调大小 + 纯尖角) 🎭
   ========================================================= */
:root {
  --sim-card-max-width: 180px; --sim-card-min-height: 120px; --sim-card-font-size: 13px; --sim-card-padding: 12px;
}
.msg-sim-card { position: relative !important; overflow: hidden !important; border-radius: 0 !important; border: none !important; cursor: pointer !important; max-width: var(--sim-card-max-width) !important; min-height: var(--sim-card-min-height) !important; padding: var(--sim-card-padding) !important; font-size: var(--sim-card-font-size) !important; line-height: 1.5 !important; }
.msg-sim-card::after { content: "" !important; position: absolute !important; top: 0 !important; left: 0 !important; right: 0 !important; bottom: 0 !important; background-image: url('https://s3.bmp.ovh/2026/08/10/GGXzrt3R.jpg') !important; background-size: cover !important; background-position: center !important; background-repeat: no-repeat !important; z-index: 10 !important; opacity: 1 !important; transition: opacity 0.25s ease !important; }
.msg-sim-card:active::after, .msg-sim-card:hover::after { opacity: 0 !important; pointer-events: none !important; }

/* 对方图片：去掉气泡 【不用改，样式容器隐藏用】 */
.msg-them:has(.msg-image-wrapper) .msg-bubble-container,
.msg-them:has(.msg-image-wrapper) .bubble-them-custom {
   background: transparent !important;
   border: none !important;
   box-shadow: none !important;
   padding: 0 !important;
}

/* ==========【修改图片最大尺寸、圆角 在这里！】========== */
/* 对方图片外层容器 */
.msg-them .msg-image-wrapper {
   /* 图片圆角值，改这里数字，8=8px圆角 */
   border-radius: 8px !important;
   overflow: hidden !important;
   border: none !important;
   box-shadow: none !important;
   background: transparent !important;
   position: relative !important;
   top: 0px !important;
   left: 0px !important;
   /* 图片最大宽度（横向上限） */
   max-width: 130px !important;
   /* 图片最大高度（纵向上限） */
   max-height: 173px !important;
   width: auto !important;
   height: auto !important;
}
/* 对方内部图片 圆角同步，改上面数字这里同步改即可 */
.msg-them .msg-image-wrapper img {
   width: 100% !important;
   height: auto !important;
   object-fit: cover !important;
   border-radius: 8px !important;
}

/* 我方图片外层容器 和上面对方参数完全一致，改这里同步尺寸圆角 */
.msg-me .msg-image-wrapper {
   /* 图片圆角 */
   border-radius: 8px !important;
   overflow: hidden !important;
   border: none !important;
   box-shadow: none !important;
   background: transparent !important;
   position: relative !important;
   top: 0px !important;
   left: 0px !important;
   /* 图片最大宽 */
   max-width: 130px !important;
   /* 图片最大高 */
   max-height: 173px !important;
   width: auto !important;
   height: auto !important;
}
/* 我方内部图片圆角 */
.msg-me .msg-image-wrapper img {
   width: 100% !important;
   height: auto !important;
   object-fit: cover !important;
   border-radius: 8px !important;
}
/* ===================================================== */

/* 去除表情包气泡 【不用改】 */
div[class*="message"] div[class*="bubble"]:has(img):not(:has([class*="avatar"])):not(:has(.msg-image-wrapper)):not(:has([class*="reply"])) {
   background: transparent !important;
   border: none !important;
   box-shadow: none !important;
   padding: 0 !important;
   border-radius: 0 !important;
   outline: none !important;
}

/* ==========【修改表情包大小 在这里！】========== */
div[class*="message"] div[class*="bubble"]:not(:has([class*="avatar"])):not(:has(.msg-image-wrapper)):not(:has([class*="reply"])) img {
   /* 表情包宽度 */
