/* 我方表情包位置 【不用改】 */
div[class*="message"] div[class*="bubble-me"]:not(:has([class*="avatar"])):not(:has(.msg-image-wrapper)):not(:has([class*="reply"])) img {
   top: 0px !important;
   left: 0px !important;
}

/* 引用内缩略图（小预览图）尺寸，单独调整这里 */
[class*="reply"] img, 
[class*="quote"] img,
.msg-reply-block-media img {
   width: 50px !important;
   height: 50px !important;
   max-width: 50px !important;
   max-height: 50px !important;
   object-fit: cover !important;
   border-radius: 4px !important;
}

/* =========================================================
   🚫 万能去气泡补丁 (转账/礼物/图片/表情包 专属净化)
